import{_ as l,a0 as o,w as r,s as c,I as e,x as s,a1 as i,A as n,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"使用 Cockpit 管理你的树莓派 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Cockpit 管理你的树莓派 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Cockpit 管理你的树莓派 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Cockpit 管理你的树莓派 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210518 Manage your Raspberry Pi with Cockpit","title":"使用 Cockpit 管理你的树莓派","tag":"202106","desc":""},"relativePath":"202106/20210518 Manage your Raspberry Pi with Cockpit.md","filePath":"[post].md"}'),d={name:"202106/20210518 Manage your Raspberry Pi with Cockpit.md"};function h(k,a,u,m,b,g){const t=o("Link");return r(),c("div",null,[a[21]||(a[21]=e("h1",{id:"使用-cockpit-管理你的树莓派",tabindex:"-1"},[s("使用 Cockpit 管理你的树莓派 "),e("a",{class:"header-anchor",href:"#使用-cockpit-管理你的树莓派","aria-label":"Permalink to “使用 Cockpit 管理你的树莓派”"},"​")],-1)),a[22]||(a[22]=e("blockquote",null,[e("p",null,"用 Cockpit 建立你的树莓派的控制中心。")],-1)),a[23]||(a[23]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202106/15/144053hmswm01w6qus011n.jpg",alt:""})],-1)),e("p",null,[a[1]||(a[1]=s("去年，我写了关于使用 ",-1)),i(t,{href:"https://opensource.com/article/20/11/cockpit-server-management"},{default:n(()=>[...a[0]||(a[0]=[s("Cockpit 管理我的 Linux 服务器的文章",-1)])]),_:1}),a[2]||(a[2]=s("。它是一个基于 Web 的工具，为管理多个服务器及其相关的服务和应用提供了一个简洁、强大的界面。它还简化了日常的管理任务。",-1))]),a[24]||(a[24]=p(`<p>在这篇文章中，我将会介绍如何在树莓派基金会提供的标准操作系统树莓派 OS 上安装用于 Linux 服务器的 Cockpit Web 控制台。我还会简要介绍它的特性。</p><h3 id="在树莓派-os-上安装-cockpit" tabindex="-1">在树莓派 OS 上安装 Cockpit <a class="header-anchor" href="#在树莓派-os-上安装-cockpit" aria-label="Permalink to “在树莓派 OS 上安装 Cockpit”">​</a></h3><p>在 <code>sudo</code> 权限下使用一个账户通过 SSH 登录你的树莓派系统。如果你还没有建立一个账户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh pibox</span></span>
<span class="line"><span>alan@pibox&#39;s password:</span></span>
<span class="line"><span>Linux pibox.someplace.org 5.10.17-v7+ #1403 SMP Mon Feb 22 11:29:51 GMT 2021 armv7l</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The programs included with the Debian GNU/Linux system are free software;</span></span>
<span class="line"><span>the exact distribution terms for each program are described in the</span></span>
<span class="line"><span>individual files in /usr/share/doc/*/copyright.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Debian GNU/Linux comes with ABSOLUTELY NO WARRANTY, to the extent</span></span>
<span class="line"><span>permitted by applicable law.</span></span>
<span class="line"><span>Last login: Tue May  4 09:55:57 2021 from 172.1.4.5</span></span>
<span class="line"><span>alan@pibox:~ $</span></span></code></pre></div><p>在树莓派 OS 上安装 Cockpit Web 控制台和在 Linux 服务器上一样简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install cockpit</span></span></code></pre></div><p>Cockpit 只需要 60.4 KB 的磁盘空间。加上它的几个包依赖项，总使用量是 115MB。</p><p>安装过程将负责设置和启动服务。你可以使用 <code>systemctl</code> 命令来验证状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl status cockpit.socket</span></span>
<span class="line"><span>● cockpit.socket - Cockpit Web Service Socket</span></span>
<span class="line"><span>   Loaded: loaded (/lib/systemd/system/cockpit.socket; enabled; vendor preset: enabled)</span></span>
<span class="line"><span>   Active: active (listening) since Tue 2021-05-04 10:24:43 EDT; 35s ago</span></span>
<span class="line"><span>     Docs: man:cockpit-ws(8)</span></span>
<span class="line"><span>   Listen: 0.0.0.0:9090 (Stream)</span></span>
<span class="line"><span>  Process: 6563 ExecStartPost=/usr/share/cockpit/motd/update-motd  localhost (code=exited, status=0/SUCCESS)</span></span>
<span class="line"><span>  Process: 6570 ExecStartPost=/bin/ln -snf active.motd /run/cockpit/motd (code=exited, status=0/SUCCESS)</span></span>
<span class="line"><span>    Tasks: 0 (limit: 2181)</span></span>
<span class="line"><span>   CGroup: /system.slice/cockpit.socket</span></span></code></pre></div><h3 id="使用-cockpit" tabindex="-1">使用 Cockpit <a class="header-anchor" href="#使用-cockpit" aria-label="Permalink to “使用 Cockpit”">​</a></h3><h4 id="连接" tabindex="-1">连接 <a class="header-anchor" href="#连接" aria-label="Permalink to “连接”">​</a></h4><p>默认的监听端口号是 9090。打开你最喜欢的 Web 浏览器并输入地址，例如： <code>https://pibox:9090</code>。</p><p><img src="https://opensource.com/sites/default/files/uploads/cockpit_homepage.png" alt="Cockpit home page" title="Cockpit home page"></p><p>你现在可以使用你的普通账户登录。同样，这个账户上需要有使用 <code>sudo</code> 的权限 —— 很可能就是你用来 SSH 和运行 Apt 的那个账户。一定要勾选“为特权任务重用我的密码”。</p><h4 id="管理你的树莓派" tabindex="-1">管理你的树莓派 <a class="header-anchor" href="#管理你的树莓派" aria-label="Permalink to “管理你的树莓派”">​</a></h4><p>Cockpit 的初始屏幕以 “System” 页开始，提供当前 CPU 和内存使用的详细信息和图表。</p><p><img src="https://opensource.com/sites/default/files/uploads/cockpit_initialscreen.png" alt="Initial Cockpit screen" title="Initial Cockpit screen"></p><p>你可以从这个屏幕看到硬件细节。</p><p><img src="https://opensource.com/sites/default/files/uploads/hardware_details.png" alt="Cockpit hardware details" title="Cockpit hardware details"></p><p>通过点击每一项来展开左边的列（例如，日志、存储、服务等）。这些是标准的 Cockpit 部分，不言自明。让我快速描述一下每个部分。</p><h4 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to “日志”">​</a></h4><p>这部分展示了日志。它们可以根据日期和严重程度来过滤。</p><h4 id="存储" tabindex="-1">存储 <a class="header-anchor" href="#存储" aria-label="Permalink to “存储”">​</a></h4><p>存储部分展示了已经安装的物理驱动器和 RAID 设备。例如大小、序列号等细节都被展示了出来。还展示了读/写活动和实际空间使用的图表。存储的具体日志显示在底部。</p><h4 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to “网络”">​</a></h4><p>这部分展示了发送和接收活动、IP 地址以及网络特定的日志。你还可以使用相应的按钮添加更多的网络设备，如绑定、网桥和 VLAN。</p><h4 id="账户" tabindex="-1">账户 <a class="header-anchor" href="#账户" aria-label="Permalink to “账户”">​</a></h4><p>这里展示了已有的账户。点击每个账户来管理，或使用创建新账户按钮来添加用户。账户也可以被删除。</p><h4 id="服务" tabindex="-1">服务 <a class="header-anchor" href="#服务" aria-label="Permalink to “服务”">​</a></h4><p>这部分可以让管理员查看系统所有服务的状态。点击任何服务都会转到一个包含启动、重启和禁用的标准任务的屏幕。</p><h4 id="应用程序" tabindex="-1">应用程序 <a class="header-anchor" href="#应用程序" aria-label="Permalink to “应用程序”">​</a></h4><p>通常，这个屏幕提供了各种用于管理功能的应用程序，例如 389 目录服务器或创建 Podman 容器。但在我的树莓派 OS 上，这个屏幕只显示“没有安装或可用的应用程序”。在写这篇文章的时候，这个或许还没有实现。虽然，你可能会怀疑这类型的程序对于树莓派硬件来说是否太过沉重。</p><h4 id="软件更新" tabindex="-1">软件更新 <a class="header-anchor" href="#软件更新" aria-label="Permalink to “软件更新”">​</a></h4><p>对任何系统管理员来说，保持软件最新是最重要的任务之一。Cockpit 的软件更新部分可以检查并进行更新。</p><p><img src="https://opensource.com/sites/default/files/uploads/software_updates.png" alt="Software updates in Cockpit" title="Software updates in Cockpit"></p><h4 id="终端" tabindex="-1">终端 <a class="header-anchor" href="#终端" aria-label="Permalink to “终端”">​</a></h4>`,36)),e("p",null,[a[4]||(a[4]=s("Cockpit 最方便的特点之一是终端。你可以使用它，而不是打开一个单独的终端模拟器并使用 SSH。我使用终端来安装 ",-1)),i(t,{href:"https://opensource.com/article/20/1/screenfetch-neofetch"},{default:n(()=>[...a[3]||(a[3]=[s("ScreenFetch",-1)])]),_:1}),a[5]||(a[5]=s("：",-1))]),a[25]||(a[25]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install screenfetch</span></span></code></pre></div><p>使用 ScreenFetch 生成了这张截图：</p><p><img src="https://opensource.com/sites/default/files/uploads/pi_cockpit_terminal.png" alt="Terminal in Cockpit" title="Terminal in Cockpit"></p><h3 id="使用-cockpit-的中心控制" tabindex="-1">使用 Cockpit 的中心控制 <a class="header-anchor" href="#使用-cockpit-的中心控制" aria-label="Permalink to “使用 Cockpit 的中心控制”">​</a></h3><p>Cockpit 在树莓派上的表现就像它在其他 Linux 系统上一样。你可以将它添加到仪表盘上进行集中控制。它允许企业在 Cockpit 作为管理仪表盘解决方案的任何地方，将基于树莓派的服务和系统整合到他们的整体 Linux 基础设施中。因为树莓派经常在高密度机架数据中心以<ruby>无外接控制<rt>headless</rt></ruby>方式运行，而这些数据中心通常会缺乏 KVM 访问方式，这是非常方便的。</p><hr>',6)),e("p",null,[a[7]||(a[7]=s("via: ",-1)),i(t,{href:"https://opensource.com/article/21/5/raspberry-pi-cockpit"},{default:n(()=>[...a[6]||(a[6]=[s("https://opensource.com/article/21/5/raspberry-pi-cockpit",-1)])]),_:1})]),e("p",null,[a[12]||(a[12]=s("作者：",-1)),i(t,{href:"https://opensource.com/users/alanfdoss"},{default:n(()=>[...a[8]||(a[8]=[s("Alan Formy-Duval",-1)])]),_:1}),a[13]||(a[13]=s(" 选题：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[14]||(a[14]=s(" 译者：",-1)),i(t,{href:"https://github.com/ShuyRoy"},{default:n(()=>[...a[10]||(a[10]=[s("RiaXu",-1)])]),_:1}),a[15]||(a[15]=s(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:n(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[18]||(a[18]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[16]||(a[16]=[s("LCTT",-1)])]),_:1}),a[19]||(a[19]=s(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:n(()=>[...a[17]||(a[17]=[s("Linux中国",-1)])]),_:1}),a[20]||(a[20]=s(" 荣誉推出",-1))])])}const y=l(d,[["render",h]]);export{x as __pageData,y as default};
